var l=[{title:`Що змінює навантаження на коліна`,text:`Глибина присіду, висота степа, рівновага, швидкість, опір і ударне навантаження від стрибків: усе це змінює, наскільки важко працюють ваші коліна. Немає універсального правила, що коліно ніколи не має виходити за носки. Наскільки далеко коліно може комфортно рухатися, різниться між людьми та між завданнями.`},{title:`Практичні заміни`,text:`Контрольоване вставання зі стільця, спліт-присід із опорою чи низьке сходження на підвищення може бути легшим для вивчення, ніж швидкий стрибковий присід. Менш глибока чи повільніша версія може в деяких випадках відчуватися комфортніше. Коли проблема в ударі, кондиційні вправи з низьким ударним навантаженням, як-от їзда на велосипеді чи ходьба по рівній землі, можуть працювати краще за стрибки.`},{title:`Нарощуйте поступово`,text:`Почніть із руху та обсягу тренування, які переносять ваші коліна. Додавайте навантаження, глибину чи повторення лише поки симптоми лишаються прийнятними під час тренування та після нього. Не перевіряйте знову й знову болісне положення, щоб побачити, чи воно «само виправилося». Загальні поради щодо вправ не є діагнозом чи програмою реабілітації.`},{title:`Коли звертатися по допомогу`,text:`Дуже болісне, помітно деформоване чи сильно набрякле коліно, неможливість спертися на нього, заклинювання, гарячка з почервонінням чи симптоми після значної травми потребують негайної професійної оцінки. Проблеми, що не минають, також слід перевірити.`},{title:`Як це працює в TrainUp`,text:`Додайте коліна як обмеження в Профілі з нотаткою і вкажіть, чи можна стрибати. Тоді план пропускає вправи, що не підходять. Якщо вправа болить, «У мене біль» завершує її і лишає поза вашими планами, доки ви не відновите її з Профілю. Жодна вправа не гарантовано «безпечна для колін» для всіх.`}];var i=[{label:`NHS: біль у коліні та коли звертатися по допомогу`,url:`https://www.nhs.uk/symptoms/knee-pain/`},{label:`Позиційна заява ACSM 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var s={sections:l,sources:i};export{s as default,l as sections,i as sources};